window.AUTH=window.AUTH||{};window.AUTH["21-442"]={"d":"21-442","id":"2022/21-442","n":"Reed v. Goertz","briefs":[{"k":"petitioner","label":"Brief of petitioner Rodney Reed","date":"2022-07-01","url":"https://www.supremecourt.gov/DocketPDF/21/21-442/229278/20220701095716634_Reed%20v.%20Goertz%20Merits%20Brief%20FILE.pdf","side":"pet","n":67},{"k":"respondent","label":"Brief of respondent Bryan Goertz","date":"2022-08-23","url":"https://www.supremecourt.gov/DocketPDF/21/21-442/234271/20220823141831476_21-442_Brief%20for%20Respondent.pdf","side":"res","n":78},{"k":"reply","label":"Reply of petitioner Rodney Reed","date":"2022-09-22","url":"https://www.supremecourt.gov/DocketPDF/21/21-442/238539/20220922122551555_Reed%20v.%20Goertz%20Merits%20Reply%20Brief%20FILE.pdf","side":"pet","n":35}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us1r12_l5gm.pdf","tr":true,"items":[{"t":"case","label":"Arizonans for Official English v. Arizona","cite":"520 U.S. 43","y":1997,"id":"1996/95-974","sc":1,"sum":"Announced by Justice Ruth Bader Ginsburg, the Court held that the dispute was moot due to the previous resignation of Yniguez. The Court did not rule on the constitutionality of the article.","sumSrc":"Oyez","by":{"0":"38, 49"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"0":"35","2":"4, 5, 15"}},{"t":"case","label":"Berger v. North Carolina State Conference of the NAACP","cite":"2022 WL 2251306","y":2022,"court":"U.S. June 23","by":{"0":"42, 44"}},{"t":"case","label":"Bouie v. City of Columbia","cite":"378 U.S. 347","y":1964,"id":"1963/10","sc":1,"op":2,"sum":"The State Supreme Court, in giving retroactive application to its new construction of the statute, has deprived petitioners of their right to fair warning of a criminal prohibition, and thus has violated the Due Process Clause of the Fourteenth Amendment. Pp. 348-363. 239 S. C. 570, 124 S. E. 2d 332, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 34"}},{"t":"case","label":"Brewer v. State","cite":"2017 WL 3392719","y":2017,"court":"Tex. App. Aug. 8","by":{"0":"44"}},{"t":"case","label":"Brinkerhoff-Faris Trust & Savings Co. v. Hill","cite":"281 U.S. 673","y":1930,"id":"scdb/1929-076","sc":1,"op":3,"sum":"1. A federal claim first raised by petition for rehearing in a state court is in time for purposes of review here if it was raised at the first opportunity, even though the-petition was denied without opinion.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 34, 35"}},{"t":"case","label":"California v. Texas","cite":"141 S. Ct. 2104","y":2021,"id":"2020/19-840","sc":1,"sum":"Plaintiffs lack standing to challenge the Patient Protection and Affordable Care Act’s minimum essential coverage provision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"45","1":"37, 38, 39","2":"5, 6"}},{"t":"case","label":"Carey v. Piphus","cite":"435 U.S. 247","y":1978,"id":"1977/76-1149","sc":1,"sum":"The Court held that the purpose of the Civil Rights Act of 1871 is to compensate people for injuries caused by the deprivation of civil rights, which means that compensation cannot occur without proof of injury. However, the definition of injury must be adapted to fit the civil rights in question.","sumSrc":"Oyez","by":{"0":"18, 25, 31","2":"12, 14"}},{"t":"case","label":"Communist Party of the United States v. Subversive Activities Control Board","cite":"367 U.S. 1","y":1961,"id":"1960/12","sc":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Connecticut Board of Pardons v. Dumschat","cite":"452 U.S. 458","y":1981,"id":"1980/79-1997","sc":1,"sum":"The power vested in the Connecticut Board of Pardons to commute sentences conferred no rights on respondents beyond the right to seek commutation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8"}},{"t":"case","label":"Cooper v. Oklahoma","cite":"517 U.S. 348","y":1996,"id":"1995/95-5207","sc":1,"op":1,"sum":"The Court held that because Oklahoma's procedural rule allows the State to try a defendant who is more likely than not incompetent, it violates due process.","sumSrc":"Oyez","by":{"0":"31, 32","2":"14"}},{"t":"case","label":"Cope v. Anderson","cite":"331 U.S. 461","y":1947,"id":"scdb/1946-106","sc":1,"sum":"1. Within the meaning of the Ohio \"borrowing statute,\" the \"cause of action\" in a suit brought in Ohio against residents of that State to enforce their statutory double liability on shares of an insolvent Kentucky national bank \"arose\" in Kentucky, and the applicable statute of limitations was the five-year statute of Kentucky.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"District Attorney’s Office for Third Judicial District v. Osborne","cite":"557 U.S. 52","y":2009,"id":"2008/08-6","sc":1,"op":4,"sum":"The Court found that the defendant had no constitutional right to obtain post-conviction access to DNA evidence used against him at trial.","sumSrc":"Oyez","by":{"0":"29, 30, 31, 32, 36, 38, 46, 48","1":"4, 35","2":"13, 14, 15, 18, 22"}},{"t":"case","label":"District of Columbia Court of Appeals v. Feldman","cite":"460 U.S. 462","y":1983,"id":"1982/81-1335","sc":1,"op":5,"sum":"Respondents filed petitions in the District of Columbia Court of Appeals asking for waivers of that court's District of Columbia Bar admission rule that requires applicants to have graduated from a law school approved by the American Bar Association. The court issued per curiam orders denying the petitions. Respondents then filed complaints in the United States District Court for the District of Columbia, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 40, 41","1":"41"}},{"t":"case","label":"Ewere v. State","cite":"2017 WL 5559585","y":2017,"court":"Tex. App. Nov. 16","by":{"0":"44"}},{"t":"case","label":"Exxon Mobil Corp. v. Saudi Basic Industries Corp.","cite":"544 U.S. 280","y":2005,"id":"2004/03-1696","sc":1,"op":2,"sum":"The Court held that the the Third Circuit \"misperceived the narrow ground occupied by Rooker-Feldman.\" That doctrine was confined to cases brought by state-court losers complaining of state-court judgments made before the federal district court proceedings began and inviting district court rejection of those judgments.","sumSrc":"Oyez","by":{"0":"40","1":"42"}},{"t":"case","label":"Federal Election Comission v. Cruz","cite":"142 S. Ct. 1638","y":2022,"id":"2021/21-12","sc":1,"op":1,"sum":"Section 304 of the Bipartisan Campaign Reform Act of 2002—which limits the amount of post-election contributions that may be used to repay a candidate who lends money to his own campaign—unconstitutionally burdens core political speech.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"45","2":"5"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"op":4,"ar":1,"sum":"Evaluating the Secretary's chosen procedure under Article I Section 2 of the Constitution, however, Justice O'Connor ruled that the decision to include overseas personnel of the Department of Defense was a reasonable interpretation of the Constitution's intent. \"The Secretary's judgment does not hamper the underlying constitutional goal of equal representation, but, assuming that employees temporarily stationed abroad have indeed retained their ties to their home states, actually promotes equality,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"0":"45","2":"5"}},{"t":"case","label":"Gabelli v. Securities & Exchange Commission","cite":"568 U.S. 442","y":2013,"id":"2012/11-1274","sc":1,"sum":"The Court held that a five-year statute of limitations period begins at the time the violation is committed.","sumSrc":"Oyez","by":{"0":"18, 25","2":"13, 15, 21"}},{"t":"case","label":"Green v. Brennan","cite":"578 U.S. 547","y":2016,"id":"2015/14-613","sc":1,"sum":"The Court held that the 45-day period in which an employee must file a constructive discharge claim under federal employment discrimination law begins to run on the date the employee resigns.","sumSrc":"Oyez","by":{"0":"27, 38","2":"18"}},{"t":"case","label":"Heck v. Humphrey","cite":"512 U.S. 477","y":1994,"id":"1993/93-6188","sc":1,"sum":"The Supreme Court held that a defendant cannot claim damages for an allegedly unconstitutional conviction or imprisonment without showing that the conviction or sentence has been overturned in some way. The defendant must also exhaust state court remedies before bringing a §1983 action.","sumSrc":"Oyez","by":{"0":"9, 35, 36"}},{"t":"case","label":"Howlett ex rel. Howlett v. Rose","cite":"496 U.S. 356","y":1990,"id":"1989/89-5383","sc":1,"sum":"A state-law \"sovereign immunity\" defense is not available to a school board in a § 1983 action brought in a state court that otherwise has jurisdiction when such defense would not be available if the action were brought in a federal forum.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Hudson v. Palmer","cite":"468 U.S. 517","y":1984,"id":"1983/82-1630","sc":1,"sum":"The Court held that the Fourth Amendment proscription against unreasonable searches did not apply \"within the confines of the prison cell.\" Noting that privacy was fundamentally incompatible with the maintenance of prison security and surveillance, the Court found that \"the paramount interest in institutional security\" outweighed all privacy concerns.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Kalina v. Fletcher","cite":"522 U.S. 118","y":1997,"id":"1997/96-792","sc":1,"sum":"The Court held that section 1983 may create a damages remedy against a prosecutor for making false statements of fact in an affidavit supporting an application for an arrest warrant, since such conduct is not protected by the doctrine of absolute prosecutorial immunity.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Kennedy v. Louisiana","cite":"554 U.S. 407","y":2008,"id":"2007/07-343","sc":1,"op":1,"ar":1,"sum":"The Court held that the Eighth Amendment prevented states from imposing the death penalty for the rape of a child, in which death was not intended nor resulted from the rape.","sumSrc":"Oyez","by":{"0":"34, 35"}},{"t":"case","label":"Larson v. Valente","cite":"456 U.S. 228","y":1982,"id":"1981/80-1666","sc":1,"sum":"The Court held that the fifty percent rule clearly distinguished between denominations and created denominational preferences within the law, and it did not serve a compelling government interest. The Court also held that the Act failed the three-part test established in Lemon v. Kurtzman by fostering the government entanglement in religion.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Logan v. Zimmerman Brush Co.","cite":"455 U.S. 422","y":1982,"id":"1981/80-5950","sc":1,"sum":"The judgment is reversed, and the case is remanded. 82 Ill. 2d 99, 411 N. E. 2d 277, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 47"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"op":2,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"0":"23","2":"4, 5"}},{"t":"case","label":"Manuel v. City of Joliet","cite":"137 S. Ct. 911","y":2017,"id":"2016/14-9496","sc":1,"ar":2,"sum":"The Court held that an individual’s right to be free from unreasonable search and seizure continues throughout the legal process of a criminal case.","sumSrc":"Oyez","by":{"0":"7, 18, 24, 25, 46","2":"14, 15, 19, 20"}},{"t":"case","label":"Mata v. Lynch","cite":"576 U.S. 143","y":2015,"id":"2014/14-185","sc":1,"sum":"The Court held that circuit courts of appeals have jurisdiction over Board of Immigration Appeals decisions to deny motions to reopen immigration proceedings.","sumSrc":"Oyez","by":{"0":"41","2":"4"}},{"t":"case","label":"McDonough v. Smith","cite":"139 S. Ct. 2149","y":2019,"id":"2018/18-485","sc":1,"op":4,"ar":5,"sum":"The Court held that the statute of limitations for the petitioner’s § 1983 fabricated evidence claim began to run when the criminal proceedings against him terminated in his favor—that is, when he was acquitted at the end of his second trial.","sumSrc":"Oyez","by":{"0":"36, 37, 38, 39, 46, 49","2":"12, 15, 17, 20, 23"}},{"t":"case","label":"Medina v. California","cite":"505 U.S. 437","y":1992,"id":"1991/90-8370","sc":1,"op":2,"sum":"Before petitioner Medina's trial for, inter alia, first-degree murder, the California court granted his motion for a competency hearing pursuant to a state law that forbids a mentally incompetent person to be tried or punished, establishes a presumption of competence, and placed on petitioner the burden of proving incompetence by a preponderance of the evidence. The jury empaneled for the competency hearing found …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9"}},{"t":"case","label":"Monell v. Department of Social Services","cite":"436 U.S. 658","y":1978,"id":"1977/75-1914","sc":1,"sum":"The Court held that the legislative history of the Civil Rights Act of 1871, and specifically the Sherman Amendment, indicated that municipalities could be liable for the infringement of constitutional rights. Additionally, by 1871 there was a clear legislative and precedent-based history for municipal corporations — such as a school board — to be considered a “person” for the purpose of lawsuits and liability.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Moore v. Texas","cite":"137 S. Ct. 1039","y":2017,"id":"2016/15-797","sc":1,"sum":"The Court determined that the use of outdated medical standards regarding intellectual disability to determine whether a person is exempt from execution violates the Eighth Amendment’s prohibition against cruel and unusual punishment as well as earlier precedent.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Nance v. Ward","cite":"2022 WL 2251307","y":2022,"court":"U.S. June 23","by":{"0":"2, 32, 38, 48, 49"}},{"t":"case","label":"Napue v. Illinois","cite":"360 U.S. 264","y":1959,"id":"1958/583","sc":1,"sum":"The failure of the prosecutor-to correct the testimony of the witness which he knew to be false denied petitioner due process of law in violation of-the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Nieves v. Bartlett","cite":"139 S. Ct. 1715","y":2019,"id":"2018/17-1174","sc":1,"sum":"Because police officers had probable cause to arrest Bartlett, his First Amendment retaliatory arrest claim fails as a matter of law.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"35"}},{"t":"case","label":"Papasan v. Allain","cite":"478 U.S. 265","y":1986,"id":"1985/85-499","sc":1,"sum":"Federal school land grants to Mississippi in the early 19th century did not apply to lands in northern Mississippi that were held by the Chickasaw Indian Nation, an area that came to be the northern 23 counties in the State. The Chickasaws thereafter ceded this area to the United States by a treaty under which the lands were sold, but no lands for public schools (Sixteenth Section lands) were reserved from sale. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42, 43","2":"7"}},{"t":"case","label":"Perry v. New Hampshire","cite":"565 U.S. 228","y":2012,"id":"2011/10-8974","sc":1,"sum":"The Court held that the Due Process Clause does not require a preliminary inquiry into the reliability of an eyewitness' identification unless the ID was brought about under unnecessarily suggestive circumstances.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Railroad Commission of Texas v. Pullman Co.","cite":"312 U.S. 496","y":1941,"id":"scdb/1940-063","sc":1,"sum":"'Shaw v. Moore, 104 Vt. 529; 162 A. 373; Franzoni v. Ravenna, 105 Vt. 64; 163 A. 564; Anderson v. Olson, 106 Vt. 70; 184 A. 712; L'Ecuyer v. Farnsworth,106 Vt. 180; 170 A. 677;. Garvey v. Michaud, 108 Vt. 226; \"184 A. 712; Kelley v. Anthony, 110 Vt. 490; 8 A. 2d 641. \"Dessereauv. Walker, 105 Vt. 99; 163 A. 632; Farrenv. McMahon, 110 Vt. 55; 1 A. 2d 726; Hunter v. Preston, 105 Vt. 327, 338; 166 A. 17; Hall v. Royce, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49","1":"36"}},{"t":"case","label":"Reed v. Texas","cite":"140 S. Ct. 686","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/686/","sc":1,"by":{"0":"2, 10, 11, 12"}},{"t":"case","label":"Reed v. Texas","cite":"534 U.S. 955","y":2001,"url":"https://supreme.justia.com/cases/federal/us/534/955/","sc":1,"by":{"0":"11","1":"3"}},{"t":"case","label":"Reed v. Texas","cite":"138 S. Ct. 2675","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./138/2675/","sc":1,"by":{"0":"14","1":"8, 44"}},{"t":"case","label":"Rehberg v. Paulk","cite":"566 U.S. 356","y":2012,"id":"2011/10-788","sc":1,"sum":"The Court held that a witness in a grand jury proceeding is entitled to the same absolute immunity from a §1983 action as a witness who testifies at trial.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Rogers v. Tennessee","cite":"532 U.S. 451","y":2001,"id":"2000/99-6218","sc":1,"op":2,"ar":1,"sum":"The Court held that the Tennessee Supreme Court's retroactive application to a defendant of its decision abolishing the year-and-a-day rule did not deny Rogers due process of law in violation of the Fourteenth Amendment. \"The Tennessee court's abolition of the year and a day rule was not unexpected and indefensible,\" wrote Justice O'Connor. \"Far from a marked and unpredictable departure from prior precedent, the court's decision was a routine exercise of common law decisionmaking in which the court brought the law into conformity with reason and common sense,\" continued O'Connor.","sumSrc":"Oyez","by":{"0":"33, 34"}},{"t":"case","label":"Rooker v. Fidelity Trust Co.","cite":"263 U.S. 413","y":1923,"id":"scdb/1923-051","sc":1,"op":13,"ar":7,"sum":"1. Where a judgment has been rendered, after due hearing, by a state trial court, with jurisdiction of the subject matter and parties, and affirmed by the state Supreme Court, the only resort under the","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 40","1":"41"}},{"t":"case","label":"Shelley v. Kraemer","cite":"334 U.S. 1","y":1948,"id":"1940-1955/334us1","sc":1,"sum":"The Court ruled that enforcement of racially restrictive covenants were a violation of the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Skinner v. Switzer","cite":"562 U.S. 521","y":2011,"id":"2010/09-9000","sc":1,"op":6,"sum":"Stating that “a prisoner could exit the state court procedures at any point” and bring a challenge.","sumSrc":"opinion","by":{"0":"26, 28, 29, 30, 38, 40, 43, 48","1":"passim","2":"14, 16, 18, 22, 23"}},{"t":"case","label":"Smith v. State","cite":"165 S.W.3d 361","y":2005,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.3d/165/361/","by":{"0":"31, 47","2":"17"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Environment","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"op":1,"ar":2,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"0":"22","1":"39"}},{"t":"case","label":"Thompson v. Clark","cite":"142 S. Ct. 1332","y":2022,"id":"2021/20-659","sc":1,"sum":"Petitioner Thompson’s showing that his criminal prosecution ended without a conviction satisfies the requirement to demonstrate a favorable termination of a criminal prosecution in a Fourth Amendment claim under 42 U. S. C. §1983 for malicious prosecution; an affirmative indication of innocence is not needed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"5, 49"}},{"t":"case","label":"Verizon Maryland Inc. v. Public Service Commission","cite":"535 U.S. 635","y":2002,"id":"2001/00-1531","sc":1,"sum":"The Court held that the district court had jurisdiction, so as to review the Commission's order for compliance with federal law, to entertain the suit because resolution of the LEC's claim turned on whether the Act, or an FCC ruling issued thereunder, precluded the state commission from ordering payment of reciprocal compensation.","sumSrc":"Oyez","by":{"0":"23, 42, 43"}},{"t":"case","label":"Wainwright v. Goode","cite":"464 U.S. 78","y":1983,"id":"1983/83-131","sc":1,"sum":"Respondent was convicted of murder in a Florida state court, and the trial judge sentenced him to death. The Florida Supreme Court affirmed. Thereafter, respondent filed a motion in state court to vacate the conviction and sentence, contending that the sentencing judge considered an aggravating circumstance-future dangerousness-that is impermissible under Florida law. The motion was denied, and the denial was …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","1":"30"}},{"t":"case","label":"Wallace v. Kato","cite":"549 U.S. 384","y":2007,"id":"2006/05-1240","sc":1,"op":4,"ar":8,"sum":"The opinion by Justice Antonin Scalia held that \"the statute of limitations begins to run when the alleged false imprisonment ends.\" Since false imprisonment is detention without legal process, the Court ruled, the false imprisonment ends when legal processes begin. At that point, the clock begins to run on the time limit for filing a false imprisonment claim.","sumSrc":"Oyez","by":{"0":"4, 18, 25, 30, 36, 37, 47","1":"passim","2":"10, 12, 19, 20"}},{"t":"case","label":"Watkins v. Texas","cite":"619 S.W.3d 265","y":2021,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.3d/619/265/","by":{"0":"27"}},{"t":"case","label":"Wearry v. Cain","cite":"577 U.S. 385","y":2016,"id":"2015/14-10008","sc":1,"sum":"The Court held that, to prevail on a claim that suppression of evidence violated his due process rights, a defendant need only show that the suppressed evidence was sufficient to undermine confidence in the verdict.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Wilson v. Garcia","cite":"471 U.S. 261","y":1985,"id":"1984/83-2146","sc":1,"sum":"The Court held that, in situations where a federal action does not have a statute of limitations, the practice has been to adopt a local limitation as long as that limitation is not inconsistent with a federal law or policy.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Woodford v. Ngo","cite":"548 U.S. 81","y":2006,"id":"2005/05-416","sc":1,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that a prisoner must properly exhaust any available administrative remedies before bringing suit in federal court. This understanding of the PLRA's exhaustion provision mirrors that of the traditional exhaustion provision in administrative law and is \"substantively similar\" to that of habeas corpus law.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Younger v. Harris","cite":"401 U.S. 37","y":1971,"id":"1970/2","sc":1,"sum":"In an 8-to-1 decision, the Court held that \"settled doctrines\" of federalism narrowly confined the availability of injunctive relief against state criminal prosecutions.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Zinermon v. Burch","cite":"494 U.S. 113","y":1990,"id":"1989/87-1965","sc":1,"op":4,"sum":"Burch's complaint was sufficient to state a claim under § 1983 for violation of his procedural due process rights. While Parrattand Hudson apply to deprivations of liberty, they do not preclude Burch's claim, because predeprivation procedural safeguards might have been of value in preventing the alleged deprivation of Burch's liberty without either valid consent or an involuntary placement hearing. Such a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 19, 30, 46, 47","2":"11, 12, 13, 15, 21"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"0":"6","1":"9"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","by":{"0":"35"}},{"t":"usc","label":"27 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/27/1257","ar":1,"tname":"Intoxicating Liquors","by":{"0":"40"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"6"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","stext":{"head":"§1331. Federal question","paras":[[0,"The district courts shall have original jurisdiction of all civil actions arising under the Constitution, laws, or treaties of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1331?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1331. Federal question","tname":"Judiciary and Judicial Procedure","by":{"0":"40"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","by":{"0":"35"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":31,"ar":4,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"30, 32, 35, 36, 37, 38, 39, 40, 46, 47, 48, 49, 50","1":"passim","2":"10, 11, 19, 23"}},{"t":"case","label":"Alvarez v. Att’y Gen. for Fla.","cite":"679 F.3d 1257","y":2012,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/679/1257/","by":{"1":"43"}},{"t":"case","label":"Bay Area Laundry & Dry Cleaning Pension Tr. Fund v. Ferbar Corp. of Cal.","cite":"522 U.S. 192","y":1997,"id":"1997/96-370","sc":1,"op":1,"sum":"The Court held that the MPPAA's six-year statute of limitations on a pension fund's action to collect unpaid withdrawal liability does not begin to run until the employer fails to make a payment on the schedule set by the fund.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Brazos Elec. Power Coop., Inc. v. Tex. Comm’n on Envtl. Quality","cite":"576 S.W.3d 374","y":2019,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/576/374/","by":{"1":"26"}},{"t":"case","label":"Brooks v. State","cite":"323 S.W.3d 893","y":2010,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.3d/323/893/","by":{"1":"27, 28"}},{"t":"case","label":"Cal. Pub. Emps’ Ret. Sys. v. ANZ Sec., Inc.","cite":"137 S. Ct. 2042","y":2017,"id":"2016/16-373","sc":1,"sum":"The Court determined that the filing of a putative class action lawsuit does not satisfy the three-year time limit in Section 13 of the Securities Act with respect to the individual claims of other class members.","sumSrc":"Oyez","by":{"1":"13, 14, 29, 34"}},{"t":"case","label":"Calderon v. Thompson","cite":"523 U.S. 538","y":1998,"id":"1997/97-215","sc":1,"sum":"The Court held that although it was consistent with the Antiterrorism and Effective Death Penalty Act of 1996, the recall was a grave abuse of discretion.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"City and County of San Francisco v. Sheehan","cite":"575 U.S. 600","y":2015,"id":"2014/13-1412","sc":1,"sum":"The Court held that an unwarranted entry does not violate the Fourth Amendment when it does not violate a clearly established constitutional or statutory right and is reasonable under the circumstances.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Concepcion v. United States","cite":"142 S. Ct. 2389","y":2022,"id":"2021/20-1650","sc":1,"sum":"Section 404(b) of the First Step Act of 2018, 132 Stat. 5222, allows district courts to consider intervening changes of law or fact in exercising their discretion to reduce a sentence.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23"}},{"t":"case","label":"Cooper Indus., Inc. v. Aviall Servs., Inc.","cite":"543 U.S. 157","y":2004,"id":"2004/02-1192","sc":1,"sum":"The Court held that a private party, who, like Aviall, had not been sued under CERCLA could not obtain cleanup contributions from other liable parties. The Court reasoned that CERCLA's language made clear that parties could seek cleanup contribution only during or following a civil action.","sumSrc":"Oyez","by":{"1":"20, 39"}},{"t":"case","label":"Cooper v. Ramos","cite":"704 F.3d 772","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/704/772/","by":{"1":"43"}},{"t":"case","label":"Cromartie v. Shealy","cite":"941 F.3d 1244","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/941/1244/","by":{"1":"20"}},{"t":"case","label":"(ctd.) CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"1":"13, 34, 37"}},{"t":"case","label":"Del. State Coll. v. Ricks","cite":"449 U.S. 250","y":1980,"id":"1980/79-939","sc":1,"sum":"Respondent's Title VII and § 1981 claims were untimely.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32, 35, 36, 37"}},{"t":"case","label":"Donado v. PennyMac Corp.","cite":"174 So. 3d 1041","y":2015,"court":"Fla. App. Ct.","url":"https://www.courtlistener.com/c/So.%203d/174/1041/","by":{"1":"25"}},{"t":"case","label":"Duke Power Co. v. Carolina Env’t Study Grp., Inc.","cite":"438 U.S. 59","y":1978,"id":"1977/77-262","sc":1,"sum":"The Price-Anderson Act (Act), having the dual purpose of protecting the public and encouraging the development of the nuclear energy industry, imposes a $560 million limitation on liability for nuclear accidents resulting from the operation of federally licensed private nuclear power plants, requires those indemnified by the $560 million fund established under the Act to waive all legal defenses in the event of a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Edwards v. Balisok","cite":"520 U.S. 641","y":1997,"id":"1996/95-1352","sc":1,"op":1,"sum":"The Court held that Balisok's \"claim for declaratory relief and monetary damages, based on allegations of deceit and bias on the part of the decisionmaker that necessarily imply the invalidity of the punishment imposed, is not cognizable....\".","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Ervin v. State","cite":"331 S.W.3d 49","url":"https://www.courtlistener.com/c/S.W.3d/331/49/","by":{"1":"28"}},{"t":"case","label":"Esteves v. Brock","cite":"106 F.3d 674","y":1997,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/106/674/","by":{"1":"40"}},{"t":"case","label":"Ford Motor Co. v. Dep’t of Treasury of Ind.","cite":"323 U.S. 459","y":1945,"id":"scdb/1944-058","sc":1,"sum":"1. A suit against the Department of Treasury of the State of Indiana and individuals constituting the \"Board of the Department of Treasury,\" brought pursuant to § 64-2614 of Burns' Indiana Statutes Annotated (1943 Replacement) for a refund of taxes alleged to have been illegally collected, held a suit against the State, in respect of which the State had not consented to the jurisdiction of the federal district court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40"}},{"t":"case","label":"Franka v. Velasquez","cite":"332 S.W.3d 367","y":2011,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/332/367/","by":{"1":"27"}},{"t":"case","label":"Glob. Naps, Inc. v. Verizon New England, Inc.","cite":"489 F.3d 13","y":2007,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/489/13/","sum":"Noting that a party “could have been expected to treat” the court’s prior decision “as good law, notwithstanding the ministerial fact that the mandate had not yet issued”.","sumSrc":"brief:1","by":{"1":"24"}},{"t":"case","label":"(ctd.) Green v. State","cite":"872 S.W.2d 717","y":1994,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.2d/872/717/","by":{"1":"27"}},{"t":"case","label":"Griego v. State","cite":"2010 WL 4225863","y":2010,"court":"Tex. App.—Amarillo Oct. 26","by":{"1":"28"}},{"t":"case","label":"Herndon v. Lowry","cite":"301 U.S. 242","y":1937,"id":"scdb/1936-115","sc":1,"sum":"that the scope of habeas corpus, in the circumstances, was a local question and that the ruling on the federal question was open to review by this Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Holmes Grp., Inc. v. Vornado Air Circulation Sys., Inc.","cite":"535 U.S. 826","y":2002,"id":"2001/01-408","sc":1,"sum":"The Court held that the appellate could not assert jurisdiction over such a case.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Jackson v. Virginia","cite":"443 U.S. 307","y":1979,"id":"1978/78-5283","sc":1,"op":1,"sum":"Petitioner was convicted of first-degree murder after a bench trial in a Virginia court, and his motion and petition in the state courts to set aside the conviction on the ground that there was insufficient evidence of premeditation, a necessary element of first-degree murder, were denied. He then brought a habeas corpus proceeding in Federal District Court, which, applying the \"no evidence\" criterion of Thompson v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Johnson v. De Grandy","cite":"512 U.S. 997","y":1994,"id":"1993/92-519","sc":1,"op":1,"sum":"In these consolidated cases, a group of Hispanic voters, a group of black voters, and the Federal Government claim that Florida's reapportionment plan for the State's single-member Senate and House districts (SJR 2-G) unlawfully dilutes the voting strength of Hispanics and blacks in the Dade County area, in violation of §2 of the Voting Rights Act of 1965. The State Supreme Court, in a review required by the State …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Lance v. Dennis","cite":"546 U.S. 459","y":2006,"id":"2005/05-555","sc":1,"sum":"The Court held that \"The Rooker-Feldman doctrine does not bar actions by nonparties to the earlier state-court judgment simply because [...] they could be considered in privity with a party to the judgment.\" Since Lance was not a party to the state-court suit, and was in no position to appeal the Colorado Supreme Court's decision, the District Court had jurisdiction to hear the case.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Lesh v. Johnston Furniture Co.","cite":"13 N.E.2d 708","y":1938,"court":"Ind.","url":"https://www.courtlistener.com/c/N.E.2d/13/708/","by":{"1":"26"}},{"t":"case","label":"Madison v. Alabama","cite":"139 S. Ct. 718","y":2019,"id":"2018/17-7505","sc":1,"op":1,"sum":"The Eighth Amendment may permit executing a prisoner even if he cannot remember committing his crime but it may prohibit executing a prisoner who suffers from dementia or another disorder rather than psychotic delusions.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16"}},{"t":"case","label":"Mason v. State","cite":"416 S.W.3d 720","url":"https://www.courtlistener.com/c/S.W.3d/416/720/","by":{"1":"27"}},{"t":"case","label":"McCleskey v. Zant","cite":"499 U.S. 467","y":1991,"id":"1990/89-7024","sc":1,"sum":"McCleskey's failure to raise his Massiah claim in his first federal habeas petition constituted abuse of the writ.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"(ctd.) McDougall v. County of Ventura","cite":"38 F.4th 1162","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/38/1162/","by":{"1":"23"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Morrison v. Chan","cite":"699 S.W.2d 205","y":1985,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/699/205/","by":{"1":"26"}},{"t":"case","label":"Mullaney v. Wilbur","cite":"421 U.S. 684","y":1975,"id":"1974/74-13","sc":1,"sum":"The Maine rule does not comport with the requirement of the Due Process Clause of the Fourteenth Amendment that the prosecution must prove beyond a reasonable doubt every fact necessary to constitute the crime charged, In re Winship, 397 U. S. 358. To satisfy that requirement the prosecution in a homicide case in Maine must prove beyond a reasonable doubt the absence of the heat of passion on sudden provocation when …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Musacchio v. United States","cite":"577 U.S. 237","y":2016,"id":"2015/14-1095","sc":1,"sum":"The Court determined that the law of the case doctrine does not require that the sufficiency of evidence be measured against the elements laid out in the jury instructions when those elements require the government to prove more than the statute requires and the government did not object at trial. The Court also determined that a statute of limitations defense that is not raised at trial is not reviewable on appeal.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Nealon v. Williams","cite":"332 S.W.3d 364","y":2011,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/332/364/","by":{"1":"26-27"}},{"t":"case","label":"N.Y. York State Rifle & Pistol Ass’n, Inc. v. Bruen","cite":"142 S. Ct. 2111","y":2022,"id":"2021/20-843","sc":1,"sum":"New York’s proper-cause requirement for obtaining an unrestricted license to carry a concealed firearm violates the Fourteenth Amendment in that it prevents law-abiding citizens with ordinary self-defense needs from exercising their Second Amendment right to keep and bear arms.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23"}},{"t":"case","label":"Ohio Civil Rights Comm’n v. Dayton Christian Schs., Inc.","cite":"477 U.S. 619","y":1986,"id":"1985/85-488","sc":1,"sum":"The Court held that federal courts should abstain from adjudicating civil state proceedings in which important state interests are involved.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Oliver v. State","cite":"872 S.W.2d 713","y":1994,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.2d/872/713/","op":1,"by":{"1":"27"}},{"t":"case","label":"Reed v. Stephens","cite":"739 F.3d 753","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/739/753/","by":{"1":"3"}},{"t":"case","label":"Riley v. Northland Geriatric Ctr.","cite":"391 N.W.2d 331","y":1986,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W.2d/391/331/","by":{"1":"24"}},{"t":"case","label":"Rivers v. Roadway Express, Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"sum":"Section 101 does not apply to a case that arose before it was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Ruhrgas AG v. Marathon Oil Co.","cite":"526 U.S. 574","y":1999,"id":"1998/98-470","sc":1,"sum":"The Court held that in cases removed from a state court to federal court there is \"no unyielding jurisdictional hierarchy requiring the federal court to adjudicate subject-matter jurisdiction before considering a challenge to personal jurisdiction.\" Customarily, however, a federal court would first resolve doubts about its jurisdiction over the subject matter.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Savory v. Lyons","cite":"469 F.3d 667","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/469/667/","sum":"Explaining that, “[u]nlike habeas corpus, § 1983 does not require exhaustion in state courts”.","sumSrc":"brief:1","by":{"1":"16, 34"}},{"t":"case","label":"Scurlock Oil Co. v. Smithwick","cite":"724 S.W.2d 1","y":1986,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/724/1/","by":{"1":"21, 24-25"}},{"t":"case","label":"Searcy v. State","cite":"77 So.3d 174","y":2011,"court":"Ala. Ct. Crim. App. July 8","url":"https://www.courtlistener.com/c/So.3d/77/174/","by":{"1":"20"}},{"t":"case","label":"Shinn v. Ramirez","cite":"142 S. Ct. 1718","y":2022,"id":"2021/20-1009","sc":1,"sum":"Under 28 U. S. C. §2254(e)(2), a federal habeas court may not conduct an evidentiary hearing or otherwise consider evidence beyond the state-court record based on the ineffective assistance of state postconviction counsel.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"31, 32"}},{"t":"case","label":"(ctd.) Skinner v. State","cite":"484 S.W.3d 434","y":2016,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.3d/484/434/","by":{"1":"5","2":"7"}},{"t":"case","label":"State v. Alexander","cite":"869 S.E.2d 215","y":2022,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E.2d/869/215/","by":{"1":"20"}},{"t":"case","label":"State v. Cahill","cite":"972 N.W.2d 19","y":2022,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/972/19/","by":{"1":"20"}},{"t":"case","label":"State v. Chauvin","cite":"955 N.W.2d 684","y":2021,"court":"Minn. Ct. App.","url":"https://www.courtlistener.com/c/N.W.2d/955/684/","by":{"1":"25"}},{"t":"case","label":"State v. Harris","cite":"741 N.W.2d 1","y":2007,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/741/1/","by":{"1":"24"}},{"t":"case","label":"Sun Oil Co. v. Wortman","cite":"486 U.S. 717","y":1988,"id":"1987/87-352","sc":1,"sum":"In the 1960's and 1970's, petitioner extracted gas from properties leased from respondents in Texas, Oklahoma, and Louisiana, in exchange for agreements to pay royalties. Petitioner's prices for interstate gas sales had to be approved by the Federal Power Commission (FPC), which permitted petitioner to collect proposed increased prices from customers prior to FPC approval on the condition that petitioner comply with …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Tex. A&M Univ. Sys. v. Koseoglu","cite":"233 S.W.3d 835","y":2007,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/233/835/","by":{"1":"40"}},{"t":"case","label":"United States v. Kubrick","cite":"444 U.S. 111","y":1979,"id":"1979/78-1014","sc":1,"sum":"A claim accrues within the meaning of §2401 (b) when the plaintiff knows both the existence and the cause of his injury, and not at a later time when he also knows that the acts inflicting the injury may constitute medical malpractice. Hence, respondent's claim accrued in January 1969 when he was aware of his injury and its probable cause, and thus was barred by the 2-year statute of limitations.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"United States v. Wilson","cite":"2022 WL 2919959","y":2022,"court":"7th Cir. July 22","by":{"1":"23"}},{"t":"case","label":"Van Poyck v. McCollum","cite":"646 F.3d 865","y":2011,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/646/865/","op":1,"by":{"1":"16"}},{"t":"case","label":"Visa, Inc. v. Osborn","cite":"137 S. Ct. 289","y":2016,"id":"2016/15-961","sc":1,"sum":"A case in which the Court would have determined whether allegations that members of a business organization agreed to adhere to the organization’s rules and possessed governance rights to the organization are sufficient to plead that there was a conspiracy under the Sherman Act.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Wedbush, Noble, Cooke, Inc. v. SEC","cite":"714 F.2d 923","y":1983,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/714/923/","by":{"1":"24"}},{"t":"case","label":"Whole Women’s Health v. Jackson","cite":"142 S. Ct. 522","y":2021,"id":"2021/21-463","sc":1,"ar":1,"sum":"A pre-enforcement challenge under the Federal Constitution to Texas Senate Bill 8—the Texas Heartbeat Act—may proceed past the motion to dismiss stage against certain of the named defendants but not others; the order of the District Court is affirmed in part and reversed in part, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"41","2":"6, 7, 8"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"37"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Berger v. North Carolina State Conference of the NAACP","cite":"142 S. Ct. 2191","y":2022,"id":"2021/21-248","sc":1,"sum":"The speaker of the North Carolina State House of Representatives and the president pro tempore of the North Carolina State Senate are entitled to intervene in this litigation challenging North Carolina’s voter-ID law.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"8"}},{"t":"case","label":"Biden v. Texas","cite":"142 S. Ct. 2528","y":2022,"id":"2021/21-954","sc":1,"sum":"The Government’s rescission of Migrant Protection Protocols did not violate section 1225 of the Immigration and Nationality Act, and the then-Secretary of Homeland Security’s October 29 Memoranda constituted valid final agency action.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"3"}},{"t":"case","label":"Bucklew v. Precythe","cite":"139 S. Ct. 1112","y":2019,"id":"2018/17-8151","sc":1,"sum":"Baze v. Rees, 553 U. S. 35, and Glossip v. Gross, 576 U. S. ___, govern all Eighth Amendment challenges alleging that a method of execution inflicts unconstitutionally cruel pain; petitioner’s as-applied challenge to Missouri’s single-drug execution protocol—that it would cause him severe pain because of his particular medical condition—fails to satisfy the Baze-Glossip test.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"10, 11"}},{"t":"case","label":"El Pistolón II, Ltd. v. Levinson Alcoser Associates, L.P.","cite":"627 S.W.3d 494","y":2021,"court":"Tex. Ct. App.","url":"https://www.courtlistener.com/c/S.W.3d/627/494/","by":{"2":"16"}},{"t":"case","label":"Hughes v. Mahaney & Higgins","cite":"821 S.W.2d 154","y":1991,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/821/154/","by":{"2":"16"}},{"t":"case","label":"Lawrence v. Florida","cite":"549 U.S. 327","y":2007,"id":"2006/05-8820","sc":1,"op":1,"sum":"The Court ruled 5-4 that the time a habeas petition is pending before the Supreme Court counts toward the one-year statute of limitations in the Antiterrorism and Effective Death Penalty Act. Section 2244(d)(2) of the Act stops the clock on the time limit while the prisoner appeals in state courts, but the Court ruled that appeals to the Supreme Court are not part of the process referred to in the Act.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"McDaniel v. Precythe","cite":"897 F.3d 946","y":2018,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/897/946/","by":{"2":"8"}},{"t":"case","label":"Morales v. Trans World Airlines, Inc.","cite":"504 U.S. 374","y":1992,"id":"1991/90-1604","sc":1,"sum":"The Court held that the Airline Deregulation Act of 1978 prevents states from prohibiting deceptive airline fare advertisements through enforcement of their general consumer protection statuses.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Nance v. Ward","cite":"142 S. Ct. 2214","y":2022,"id":"2021/21-439","sc":1,"sum":"Title 42 U. S. C. §1983 is the procedural vehicle appropriate for a prisoner’s method-of-execution claim even if an order granting the relief requested would necessitate a change in state law.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"8, 18"}},{"t":"case","label":"Steffel v. Thompson","cite":"415 U.S. 452","y":1974,"id":"1973/72-5581","sc":1,"sum":"The Court held that the case presented an actual controversy, as the Georgia statute could interfere with Steffel’s exercise of his constitutional rights even if he was not arrested. Because the United States’ involvement in Vietnam, which Steffel was protesting, was reduced, the issue of whether or not the case still presented an active controversy would be decided by the lower court on remand.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Texas ex rel. Vance v. Clawson","cite":"465 S.W.2d 164","y":1971,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.2d/465/164/","by":{"2":"17"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"4"}},{"t":"case","label":"Zive v. Sandberg","cite":"644 S.W.3d 169","y":2022,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/644/169/","by":{"2":"22"}}]};